def mean(xs):return float(np.mean(xs))
def main():
 p=argparse.ArgumentParser();p.add_argument('--runs',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();a.out.mkdir(parents=True,exist_ok=True)
 fit=json.loads((a.runs/'train.json').read_text());audit=json.loads((a.runs/'audit.json').read_text());bench=json.loads((a.runs/'benchmark.json').read_text())
 rows=audit['rows'];summary={}
 for arm in ARMS:
  models=[r['arms'][arm] for r in rows];scores=[m['test']['native_rollout'] for m in models]
  summary[arm]=dict(native_exact=mean([s['native_exact'] for s in scores]),per_seed_exact=[s['native_exact'] for s in scores],first=mean([s['first_answer'] for s in scores]),second=mean([s['second_answer'] for s in scores]),both_query_orders=mean([m['counterfactual']['both_query_orders_exact'] for m in models]),native_nll=mean([s['native_nll'] for s in scores]),offsets=np.mean([[v['exact'] for v in m['offsets']] for m in models],axis=0).tolist(),delays=np.mean([[v['exact'] for v in m['delays']] for m in models],axis=0).tolist(),bytes_per_cpu_second=bench['rows'][arm]['bytes_per_cpu_second'])
 c=summary['spaced'];models=[r['arms']['spaced'] for r in rows];gates=[]
 def gate(name,value,minimum):gates.append(dict(name=name,value=float(value),minimum=minimum,pass_=bool(value>=minimum)))
 gate('primary mean native exact',c['native_exact'],.95);gate('minimum seed native exact',min(c['per_seed_exact']),.90)
 for which in ('first_answer','second_answer'):
  vals=[m['test']['native_rollout'][which] for m in models];gate(which+' mean',mean(vals),.95);gate(which+' minimum seed',min(vals),.90)
 vals=[m['counterfactual']['both_query_orders_exact'] for m in models];gate('both query orders mean',mean(vals),.90);gate('both query orders minimum seed',min(vals),.85)
 gate('all-offset mean',mean(c['offsets']),.95);gate('worst offset seed mean',min(c['offsets']),.90)
 for i,delay in enumerate((0,64,128,256)):
  vals=[m['delays'][i]['exact'] for m in models];gate(f'+{delay} delay mean',mean(vals),.90);gate(f'+{delay} delay minimum seed',min(vals),.85)
 drop=mean([m['lesion_unmodified']['native_exact']-m['lesions']['no_query']['native_exact'] for m in models]);gate('query removal drop',drop,.20)
 reversed_drop=mean([m['lesion_unmodified']['native_exact']-m['lesions']['reverse']['native_exact'] for m in models]);gate('reversed selection drop',reversed_drop,1e-12)
 gate('relative inference throughput',bench['candidate_relative_throughput'],.8)
 result=dict(stage='EXP01-D3 / EXP22',seeds=[r['seed'] for r in rows],scope='Two bindings, 48-key alphabet, two distinct binary values, native full-256 autoregressive output; separate research adapter on minimal v19',summary=summary,gates=gates,behavior_and_cost_gates_pass=all(g['pass_'] for g in gates),production_promoted=False,actual_training_bytes=63750000,added_fitted_parameters=9900,added_persistent_sequence_state_bytes=0)
 write(a.out/'summary.json',result)
 for name in ('plan.json','train.json','selection.json','audit.json','benchmark.json'):shutil.copy2(a.runs/name,a.out/('d3_'+name))
 for label,folder in [('d1',Path('/tmp/exp01d-formal')),('d2',Path('/tmp/exp01d-d2')),('d3_pilot',Path('/tmp/exp01d-d3-pilot'))]:
  for name in ('plan.json','train.json','selection.json','audit.json','benchmark.json'):
   if (folder/name).exists():shutil.copy2(folder/name,a.out/(label+'_'+name))
 for label,folder in [('d2_control',Path('/tmp/exp01d-controls')),('d3_control',Path('/tmp/exp01d-d3-controls'))]:
  for name in ('control_plan.json','positive_control.json'):
   if (folder/name).exists():shutil.copy2(folder/name,a.out/(label+'_'+name))
 for src,name in [('/tmp/exp01d-pilot-d1/plan.json','d1_pilot_plan.json'),('/tmp/exp01d-pilot-d1/result.json','d1_pilot_result.json'),('/tmp/exp01d-pilot-d1/warmup.json','d1_pilot_warmup.json'),('/tmp/exp01d_d2_intervention.json','d2_frozen_policy_development.json'),('/tmp/exp01d_d2_delay_diagnostic.json','d2_delay_development.json'),('/tmp/exp01d_compat.json','d1_policy_compatibility.json')]:
  if Path(src).exists():shutil.copy2(src,a.out/name)
 plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.titleweight':'bold','axes.labelcolor':'#29374a','text.color':'#17283b','grid.alpha':.17})
 fig,axes=plt.subplots(2,2,figsize=(13,8.6),layout='constrained');fig.suptitle('SHoEbox EXP01-D: preserve the association, then remove framing dependence',fontsize=17,fontweight='bold')
 ax=axes[0,0];xs=np.arange(4);bars=ax.bar(xs,[summary[k]['native_exact']*100 for k in ARMS],color=[COLORS[k] for k in ARMS],width=.65)
 ax.set_xticks(xs,['Native v19','Pooled','Paired\nfixed framing','Paired\nvaried framing']);ax.set_ylim(0,110);ax.set_ylabel('Both answers correct (%)');ax.set_title('A  Fresh held-out native binding');ax.axhline(95,color='#b64e47',ls='--',lw=1,label='95% gate')
 for bar in bars:ax.text(bar.get_x()+bar.get_width()/2,bar.get_height()+2,f'{bar.get_height():.2f}%',ha='center',fontweight='bold')
 ax=axes[0,1]
 for arm in ('native','unspaced','spaced'):ax.plot([0,64,128,256],np.array(summary[arm]['delays'])*100,'o-',label=LABELS[arm],color=COLORS[arm],lw=2)
 ax.axhline(90,color='#b64e47',ls='--',lw=1,label='90% delay gate');ax.set_ylim(0,105);ax.set_xticks([0,64,128,256]);ax.set_xlabel('Extra delay after records (bytes; unseen in training)');ax.set_ylabel('Both answers correct (%)');ax.set_title('B  Long delays, unchanged answer phase');ax.legend(fontsize=8,loc='lower left');ax.grid(axis='y')
 ax=axes[1,0]
 for arm in ('native','unspaced','spaced'):ax.plot(np.arange(64),np.array(summary[arm]['offsets'])*100,label=LABELS[arm],color=COLORS[arm],lw=1.7)
 ax.axhline(90,color='#b64e47',ls='--',lw=1);ax.set_ylim(0,105);ax.set_xlim(0,63);ax.set_xlabel('Answer offset modulo 64');ax.set_ylabel('Both answers correct (%)');ax.set_title('C  Every constituent boundary offset');ax.grid(axis='y')
 ax=axes[1,1];names=['intact','no_query','no_state','unpair','reverse'];values=[mean([m['lesion_unmodified']['native_exact'] for m in models])]+[mean([m['lesions'][n]['native_exact'] for m in models]) for n in names[1:]]
 bars=ax.bar(np.arange(5),np.array(values)*100,color=['#08877b','#a6acb8','#a6acb8','#d89236','#d89236']);ax.set_xticks(np.arange(5),['Intact','No query','No record\nstate','Unpaired\nvalues','Reversed\nselection']);ax.set_ylim(0,110);ax.set_ylabel('Both answers correct (%)');ax.set_title('D  Frozen interventions (same 256 cases)')
 for b in bars:ax.text(b.get_x()+b.get_width()/2,b.get_height()+2,f'{b.get_height():.1f}%',ha='center')
 fig.savefig(a.out/'SHoEbox_EXP01D_Results.png',dpi=180);plt.close(fig)
 fig,axes=plt.subplots(1,2,figsize=(12,4.8),layout='constrained');fig.suptitle('SHoEbox EXP01-D3: learning and measured CPU cost',fontsize=16,fontweight='bold')
 for arm in ARMS:
  curves=[r['arms'][arm]['curve'] for r in fit['rows']];scores=np.mean([[p['dev']['native_rollout']['native_exact'] for p in curve] for curve in curves],axis=0)*100;byte=np.mean([[p['bytes'] for p in curve] for curve in curves],axis=0)/1e6;cpu=np.mean([[p['cpu_seconds'] for p in curve] for curve in curves],axis=0)
  for ax,x in zip(axes,[byte,cpu]):ax.plot(x,scores,'o-',color=COLORS[arm],label=LABELS[arm],lw=2)
 for ax in axes:ax.set_ylim(0,105);ax.set_ylabel('Development native exactness (%)');ax.axhline(95,color='#b64e47',ls='--',lw=1);ax.grid(axis='y')
 axes[0].set_xlabel('Continuation input bytes (millions; padding included)');axes[1].set_xlabel('Continuation training CPU seconds');axes[0].legend(fontsize=9);fig.savefig(a.out/'SHoEbox_EXP01D_Learning_Cost.png',dpi=180);plt.close(fig)
 text=['# SHoEbox EXP01-D / EXP22 — constituent pairing and stable query access','', '16 November 2026 · Minimal corrected C v19 · Seeds 1, 7, 19','',f"**{'PASS' if result['behavior_and_cost_gates_pass'] else 'FAIL'}: binding behavior and cost gates.** The final readout reaches **{c['native_exact']*100:.2f}% native two-answer exactness**, versus {summary['native']['native_exact']*100:.2f}% native and {summary['pool']['native_exact']*100:.2f}% pooled. It preserves key/value pairing inside existing constituents, chooses the latest learned query cue, and learns independence from surrounding framing bytes.",'',f"All-offset mean: {mean(c['offsets'])*100:.2f}%; worst offset: {min(c['offsets'])*100:.2f}%. Both query orders: {c['both_query_orders']*100:.2f}%. Relative inference throughput: {bench['candidate_relative_throughput']*100:.2f}%. **No added persistent sequence state.** Production remains minimal v19; joint-core and language/copy/reconstruction/capacity promotion qualifications are pending.",'','![Primary results](SHoEbox_EXP01D_Results.png)','','## Final fresh audit','','| Arm | Seed 1 | Seed 7 | Seed 19 | Mean exact | First answer | Second answer | Both orders |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
 for arm in ARMS:
  s=summary[arm];text.append('| '+LABELS[arm]+' | '+' | '.join(f'{v*100:.2f}%' for v in [*s['per_seed_exact'],s['native_exact'],s['first'],s['second'],s['both_query_orders']])+' |')
 text+=['','Each seed uses 1,024 presentations / 256 concrete worlds. Record order and query order are independently balanced; sibling presentations remain in one split. Seeds share audit worlds, so 3,072 predictions are not 768 independent worlds. Task framing and query bytes are supplied. The two scored answer bytes use autoregressive argmax over all 256 bytes; generated first answers enter the second-query state. The record-encoded learned positive control is 100% for every seed, separately budgeted and never used by native inference. The strongest registered shortcut is 50%.','','## What changed','','1. **Preserve pairing.** Score all four possible phases of each existing eight-byte retained pair. Select two candidate constituents; decode each key and its value together. Query/key distances determine one shared pair of mixing weights. Only then combine the values.','2. **Separate recognition from recency.** A learned classifier recognizes query-containing two-byte constituents. Among positive candidates, select the most recent existing occurrence. Recognition confidence cannot override recency. If none is positive, use the historical score-minus-age fallback.','3. **Remove framing dependence during training.** Independently insert 0–7 padding bytes after records, and adjust leading padding so all 64 answer phases remain balanced. This varies the neighboring bytes inside a constituent. Long +64/+128/+256 delays never appear in training.','','Inference receives only existing neural state. There is no hand-coded symbol parser, selected-record index, external exact store, extra slot, history tape, optimizer moment, or replay loop. Local training supervision does identify query/record syntax in already observed windows and reconstructs observed bytes; it never performs the requested lookup. This supervised research mechanism is separate from an unsupervised language-model capability.','','## Registered gate checks','','| Gate | Measured | Required | Result |','| --- | ---: | ---: | --- |']
 for g in gates:text.append(f"| {g['name']} | {g['value']*100:.2f}% | ≥{g['minimum']*100:.2f}% | {'PASS' if g['pass_'] else 'FAIL'} |")
 text+=['','Offset sweep: identical 64 presentations / 16 worlds at every offset, per seed. Delay sweep: identical 16 presentations / four worlds crossed with all 64 offsets, separately per delay and seed. These delay checks cover padding, not arbitrary distractor writes or eviction. Counterfactual query orders fork the identical record-prefix state.','','| Extra delay | Fixed-framing paired control | Final varied-framing readout |','| --- | ---: | ---: |']
 for i,d in enumerate((0,64,128,256)):text.append(f"| +{d} bytes | {summary['unspaced']['delays'][i]*100:.2f}% | {c['delays'][i]*100:.2f}% |")
 text+=['','## Failed designs retained','','D1 preserved constituent pairing but used confidence minus age for query routing. Final development exactness was 90.04%: first answers 99.41%, second answers 90.23%. Fitting increased confidence differences enough for an older query to win. D2 replaced that competition with latest-positive recognition; a frozen development intervention alone raised exactness to 99.02%. D1 checkpoint semantics and logits remain byte-identical under the new implementation.','','D2 reached 99.41% on its primary audit and 100% over its offset sample, but approximately 86% on the longer-delay audit, failing the unchanged 90% threshold. A separate development diagnostic found query decoding stayed 100% while both-key decoding fell from 87.5% to 40.625%. The remaining failure was sensitivity to adjacent framing. D3 changed training coverage, retained the same runtime, and used a fresh audit excluding every world in the previously opened primary audit. No thresholds were relaxed.','','## Capacity, memory and work','','| Component | Fitted parameters |','| --- | ---: |','| Five local presence classifiers | 325 |','| Four record-key projections plus query projection | 5,200 |','| Four value projections | 2,080 |','| Native 255-node residual output | 2,295 |','| **Readout total** | **9,900** |','','Candidate core: 489,919 parameters; combined: 499,819, within the nominal 500K budget. Native actual capacity is 498,367; pooled control is 499,454. Small differences reflect indivisible expert banks. New readout weights occupy 39,600 bytes; forward scratch and native error storage occupy 2,108 bytes. No normalization accumulators or optimizer moments. Existing stream/retained state remains 289,152 bytes in the reported inventory. At most 16 query candidates and 64 constituent-phase candidates are scanned; only two record key/value projections are evaluated.','','| Arm | Full-distribution inference bytes/CPU-s |','| --- | ---: |']
 for arm in ARMS:text.append(f"| {LABELS[arm]} | {summary[arm]['bytes_per_cpu_second']:,.0f} |")
 text+=['','Inference timing uses a pinned CPU, 65,536 bytes per repetition, three interleaved repetitions, full 256-byte distributions on every byte, one native C++ pass. Compilation, cloning and warmup are excluded. Candidate core freezing makes training timing a frozen-readout measurement, not a speed comparison between equally trained language models.','','![Learning and CPU cost](SHoEbox_EXP01D_Learning_Cost.png)','','## Complete fitting cost','','| Stage | Charged input bytes |','| --- | ---: |','| D1 pilot | 750,000 |','| D1 four-arm, three-seed comparison | 26,250,000 |','| D2 corrected query policy, three seeds | 6,750,000 |','| D2 positive controls | 750,000 |','| D3 development pilot | 2,250,000 |','| D3 four-arm, three-seed comparison | 26,250,000 |','| D3 positive controls | 750,000 |','| **Total** | **63,750,000** |','','Every padding byte is charged. Local query/constituent reconstruction updates are additional supervised objectives within the same observed stream; counts and CPU costs are retained in raw inventories (the historical `normalization_samples` field contains local-window updates in D1–D3, not a normalizer). Correctness-test toy updates are excluded from fitted research costs. Evaluations are frozen and not training.','','## Verification and reproducibility','','See `verification.json` and its logs for the exact checks. Native parity, local derivatives, paired-source permutation, query routing, frozen read-only behavior, causal label timing, all-boundary checkpoint continuation and legacy D1-policy compatibility are checked. Optimized and ASan/UBSan checks pass. LeakSanitizer is disabled because this host runs under ptrace. Public production and historical runtime source files are unchanged. The selected checkpoints have companion training cursors containing both RNG states, remaining shuffled order and partial-episode position. A 1,000-byte continuation is byte-identical when interrupted at 371 bytes, saved/reloaded, and resumed for 629 bytes on every seed.','','The source and commands are in [experiments/constituent_readout/README.md](../../experiments/constituent_readout/README.md). Protocol and stage-specific source hashes precede fitting. D2 and D3 selections were locked before their audits. All successful and unsuccessful fits are accounted for; compact raw results accompany this report.','','## Literature and adaptation','','- Miller et al., EMNLP 2016, sections 3.1–3.2: [Key-Value Memory Networks](https://aclanthology.org/D16-1147/). Separate address/value encodings, common attention weights for associated pairs, and position-sensitive window encoding motivate the readout. Our candidates are pre-existing neural constituent pairs.','- Arora et al., ICML 2024: [Simple linear attention language models balance the recall-throughput tradeoff](https://proceedings.mlr.press/v235/arora24a.html). Motivates multi-query recall, explicit state accounting and throughput qualification; no BASED cache is added.','- Wang, Shi and Fox, JMLR 2026: [Test-time regression](https://jmlr.org/papers/v27/25-0903.html). Separates memorization from retrieval and analyzes query/key normalization; here evidence availability and learned decoding are tested separately.','','## Next development item','','EXP01-E: integrate and qualify the successful paired readout with joint native-core learning. Register language, selective-copy and bounded reconstruction regressions, plus 1M/5M binding comparisons, before changing the production default. Include a learned applicability gate for the residual and distinguish local fixture supervision from generic byte-training objectives. Keep the D3 binding/delay fixture as a regression. New slots, optimizer sweeps and reasoning loops remain outside this repair.']
 (a.out/'SHoEbox_EXP01D_Report.md').write_text('\n'.join(text)+'\n');print(json.dumps(dict(passed=result['behavior_and_cost_gates_pass'],candidate=c,gates=gates),indent=2))
if __name__=='__main__':main()
